import React, {
  useEffect,
  useReducer,
  useMemo,
  useRef,
  useState,
} from "react"

/* =========================================================
 *  文件管理器 Demo
 *  复盘 2015「命令模式 + 单向数据流」：每个交互被归约为 Command，
 *  由纯 reducer 产出新 (selection/focus/anchor/view/scrollTop) 状态，
 *  UI 仅渲染派生状态。
 *
 *  - 缩略图 / 列表视图
 *  - 鼠标拖拽框选；Shift 范围多选；Meta/Ctrl 切换选择
 *  - 方向键导航 / Shift+方向键扩展 / ⌘A 全选 / Esc 清空
 *  - 自实现固定尺寸虚拟滚动（不引三方虚拟列表库）
 * ========================================================= */

type ViewMode = "grid" | "list"
type FileKind = "folder" | "document" | "image" | "code" | "archive"

interface FileItem {
  id: number
  name: string
  kind: FileKind
  size: number
  modifiedAt: number
}

// ---- 布局常量（固定尺寸，是虚拟滚动成立的前提）----
const PAD = 16
const GRID_CELL_W = 112
const GRID_CELL_H = 108
const LIST_ROW_H = 38
const OVERSCAN = 6

// ============================================================
//  10000 条确定性数据
// ============================================================
const SEED = 20260806
const N = 10000

function mulberry32(seed: number) {
  let a = seed
  return () => {
    a |= 0
    a = (a + 0x6d2b79f5) | 0
    let t = Math.imul(a ^ (a >>> 15), 1 | a)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

function buildItems(): FileItem[] {
  const rng = mulberry32(SEED)
  const adj = [
    "final", "draft", "archived", "reviewed", "staging", "legacy",
    "experimental", "production", "backup", "snapshot", "release",
    "internal", "alpha", "beta", "rc",
  ]
  const noun = [
    "report", "invoice", "receipt", "contract", "budget", "roadmap",
    "screenshot", "catalog", "index", "config", "manifest", "build",
    "bundle", "spreadsheet", "schema", "patch", "changelog", "design",
  ]
  const ext: Record<FileKind, string[]> = {
    folder: [],
    document: ["pdf", "docx", "md", "txt"],
    image: ["png", "jpg", "svg", "webp"],
    code: ["ts", "go", "rs", "py", "sql"],
    archive: ["zip", "tar", "gz"],
  }
  const kinds: FileKind[] = ["folder", "document", "image", "code", "archive"]
  const weights = [0.16, 0.26, 0.24, 0.22, 0.12]
  const base = Date.UTC(2026, 0, 1)
  const dayMs = 86400000
  const pick = <T,>(arr: T[]): T => arr[Math.floor(rng() * arr.length)]
  const pickKind = (): FileKind => {
    const r = rng()
    let acc = 0
    for (let i = 0; i < kinds.length; i++) {
      acc += weights[i]
      if (r <= acc) return kinds[i]
    }
    return "document"
  }
  const out: FileItem[] = []
  for (let i = 0; i < N; i++) {
    const kind = pickKind()
    const name =
      kind === "folder"
        ? `${pick(adj)}-${pick(noun)}`
        : `${pick(adj)}-${pick(noun)}-${(i + 1).toString().padStart(4, "0")}.${pick(ext[kind])}`
    const size = kind === "folder" ? 0 : Math.floor(rng() * 12 * 1024 * 1024) + 512
    const modifiedAt = base - Math.floor(rng() * 365 * 8) * dayMs
    out.push({ id: i, name, kind, size, modifiedAt })
  }
  return out
}

const ITEMS = buildItems()

// ============================================================
//  命令（Command）+ Reducer
// ============================================================
interface BoxRect {
  x: number
  y: number
  w: number
  h: number
}

type FMCommand =
  | { kind: "CLICK_EMPTY" }
  | {
      kind: "CLICK_ITEM"
      id: number
      modifiers: { meta: boolean; shift: boolean; ctrl: boolean }
    }
  | { kind: "BOX"; ids: number[]; additive: boolean; box: BoxRect }
  | {
      kind: "NAVIGATE"
      dir: "up" | "down" | "left" | "right"
      extend: boolean
      from: number
      to: number
    }
  | { kind: "SELECT_ALL" }
  | { kind: "CLEAR" }
  | { kind: "VIEW"; view: ViewMode }
  // SCROLL 仅同步滚动位置，不覆盖 last（避免「当前命令」被滚动信息淹没）
  | { kind: "SCROLL"; top: number }

interface FMState {
  selection: number[]
  focus: number | null
  anchor: number | null
  view: ViewMode
  last: FMCommand | null
  scrollTop: number
}

const INITIAL: FMState = {
  selection: [],
  focus: null,
  anchor: null,
  view: "grid",
  last: null,
  scrollTop: 0,
}

function clamp(v: number, lo: number, hi: number) {
  return Math.max(lo, Math.min(hi, v))
}

const sortIdx = (xs: number[]) => xs.slice().sort((a, b) => a - b)

function rangeBetween(a: number, b: number): number[] {
  const lo = Math.min(a, b)
  const hi = Math.max(a, b)
  const out: number[] = []
  for (let i = lo; i <= hi; i++) out.push(i)
  return out
}

function reducer(state: FMState, cmd: FMCommand): FMState {
  switch (cmd.kind) {
    case "CLEAR":
      return { ...state, selection: [], last: cmd }

    case "CLICK_EMPTY":
      return { ...state, selection: [], last: cmd }

    case "SELECT_ALL":
      return {
        ...state,
        selection: rangeBetween(0, ITEMS.length - 1),
        anchor: 0,
        focus: 0,
        last: cmd,
      }

    case "VIEW":
      return { ...state, view: cmd.view, last: cmd }

    case "SCROLL":
      // 仅同步位置，保留 last 命令不被滚动淹没
      if (cmd.top === state.scrollTop) return state
      return { ...state, scrollTop: cmd.top }

    case "NAVIGATE": {
      const { to, extend } = cmd
      if (extend) {
        const a = state.anchor ?? state.focus ?? 0
        return { ...state, selection: rangeBetween(a, to), focus: to, last: cmd }
      }
      return { ...state, selection: [to], anchor: to, focus: to, last: cmd }
    }

    case "CLICK_ITEM": {
      const { id, modifiers } = cmd
      if (modifiers.shift && state.anchor != null) {
        return {
          ...state,
          selection: rangeBetween(state.anchor, id),
          focus: id,
          last: cmd,
        }
      }
      if (modifiers.meta || modifiers.ctrl) {
        const exists = state.selection.includes(id)
        const next = exists
          ? state.selection.filter((x) => x !== id)
          : state.selection.concat(id)
        return {
          ...state,
          selection: sortIdx(next),
          focus: id,
          anchor: id,
          last: cmd,
        }
      }
      return { ...state, selection: [id], anchor: id, focus: id, last: cmd }
    }

    case "BOX": {
      const { ids, additive } = cmd
      const next = additive
        ? sortIdx(Array.from(new Set(state.selection.concat(ids))))
        : sortIdx(ids)
      const focus = ids.length ? ids[ids.length - 1] : state.focus
      return { ...state, selection: next, focus, last: cmd }
    }

    default:
      return { ...state, last: cmd }
  }
}

// ============================================================
//  布局 / 几何 / 可见窗口 —— 纯函数（虚拟滚动核心）
// ============================================================
function itemsPerRow(cw: number): number {
  return Math.max(1, Math.floor((cw - PAD) / GRID_CELL_W))
}

interface LayoutInfo {
  cpr: number
  totalH: number
}
function layoutFor(view: ViewMode, cw: number): LayoutInfo {
  if (view === "grid") {
    const cpr = itemsPerRow(cw)
    const rows = Math.ceil(ITEMS.length / cpr)
    return { cpr, totalH: PAD + rows * GRID_CELL_H }
  }
  return { cpr: 1, totalH: PAD + ITEMS.length * LIST_ROW_H }
}

interface Range {
  start: number
  end: number
}
function visibleRange(view: ViewMode, cw: number, st: number, vh: number): Range {
  if (view === "grid") {
    const cpr = itemsPerRow(cw)
    const maxRow = Math.ceil(ITEMS.length / cpr) - 1
    const startRow = Math.max(0, Math.floor((st - PAD) / GRID_CELL_H) - OVERSCAN)
    const endRow = Math.min(
      maxRow,
      Math.ceil((st + vh - PAD) / GRID_CELL_H) + OVERSCAN,
    )
    return {
      start: startRow * cpr,
      end: Math.min(ITEMS.length - 1, (endRow + 1) * cpr - 1),
    }
  }
  const start = Math.max(0, Math.floor((st - PAD) / LIST_ROW_H) - OVERSCAN)
  const end = Math.min(ITEMS.length - 1, Math.ceil((st + vh) / LIST_ROW_H) + OVERSCAN)
  return { start, end }
}

interface CellRect {
  top: number
  left: number
  w: number
  h: number
}
function cellRect(view: ViewMode, idx: number, cw: number): CellRect {
  if (view === "grid") {
    const cpr = itemsPerRow(cw)
    const row = Math.floor(idx / cpr)
    const col = idx % cpr
    return {
      top: PAD + row * GRID_CELL_H,
      left: PAD + col * GRID_CELL_W,
      w: GRID_CELL_W,
      h: GRID_CELL_H,
    }
  }
  return { top: PAD + idx * LIST_ROW_H, left: PAD, w: cw - PAD, h: LIST_ROW_H }
}

function intersects(a: BoxRect, c: CellRect): boolean {
  return !(
    a.x + a.w < c.left ||
    a.x > c.left + c.w ||
    a.y + a.h < c.top ||
    a.y > c.top + c.h
  )
}

/** 框选命中下标：按行范围限定候选集，O(可见行) */
function hitTest(view: ViewMode, cw: number, box: BoxRect): number[] {
  const picks: number[] = []
  if (box.w <= 0 || box.h <= 0) return picks
  if (view === "grid") {
    const cpr = itemsPerRow(cw)
    const maxRow = Math.ceil(ITEMS.length / cpr) - 1
    const topRow = clamp(Math.floor((box.y - PAD) / GRID_CELL_H), 0, maxRow)
    const bottomRow = clamp(Math.floor((box.y + box.h - PAD) / GRID_CELL_H), 0, maxRow)
    for (let row = topRow; row <= bottomRow; row++) {
      for (let col = 0; col < cpr; col++) {
        const idx = row * cpr + col
        if (idx >= ITEMS.length) break
        if (
          intersects(box, {
            top: PAD + row * GRID_CELL_H,
            left: PAD + col * GRID_CELL_W,
            w: GRID_CELL_W,
            h: GRID_CELL_H,
          })
        )
          picks.push(idx)
      }
    }
  } else {
    const top = clamp(Math.floor((box.y - PAD) / LIST_ROW_H), 0, ITEMS.length - 1)
    const bottom = clamp(Math.floor((box.y + box.h - PAD) / LIST_ROW_H), 0, ITEMS.length - 1)
    for (let i = top; i <= bottom; i++) {
      if (intersects(box, { top: PAD + i * LIST_ROW_H, left: PAD, w: cw - PAD, h: LIST_ROW_H }))
        picks.push(i)
    }
  }
  return picks
}

// ============================================================
//  格式化
// ============================================================
function fmtSize(bytes: number): string {
  if (bytes <= 0) return "—"
  const u = ["B", "KB", "MB", "GB"]
  let v = bytes
  let i = 0
  while (v >= 1024 && i < u.length - 1) {
    v /= 1024
    i++
  }
  return `${v.toFixed(v >= 10 || i === 0 ? 0 : 1)} ${u[i]}`
}

function fmtDate(ts: number): string {
  const d = new Date(ts)
  return `${d.getFullYear()}-${(d.getMonth() + 1).toString().padStart(2, "0")}-${d
    .getDate()
    .toString()
    .padStart(2, "0")}`
}

function fmtCommand(cmd: FMCommand | null): { key: string; detail: string } {
  if (!cmd) return { key: "—", detail: "等待操作" }
  switch (cmd.kind) {
    case "CLEAR":
      return { key: "CLEAR", detail: "清空选择" }
    case "CLICK_EMPTY":
      return { key: "CLICK_EMPTY", detail: "点击空白区域" }
    case "SELECT_ALL":
      return { key: "SELECT_ALL", detail: "全选" }
    case "NAVIGATE":
      return {
        key: "NAVIGATE",
        detail: `${cmd.extend ? "Shift+" : ""}${cmd.dir}  ${cmd.from}→${cmd.to}`,
      }
    case "CLICK_ITEM": {
      const m = cmd.modifiers
      const mod = m.shift ? "Shift" : m.meta || m.ctrl ? "⌘/Ctrl" : "单击"
      return { key: "CLICK", detail: `#${cmd.id} (${mod})` }
    }
    case "BOX":
      return {
        key: "BOX",
        detail: `框选 ${cmd.ids.length} 项${cmd.additive ? " (累加)" : ""}`,
      }
    case "VIEW":
      return { key: "VIEW", detail: cmd.view === "grid" ? "缩略图" : "列表" }
    default:
      return { key: "—", detail: "" }
  }
}

