// ============================================================
//  主组件
// ============================================================
const FileManagerDemo: React.FC = () => {
  const [state, dispatch] = useReducer(reducer, INITIAL)
  const [cw, setCw] = useState(960)
  const [band, setBand] = useState<BoxRect | null>(null)

  const viewportRef = useRef<HTMLDivElement>(null)
  const itemEls = useRef<Map<number, HTMLDivElement>>(new Map())
  const pendingScroll = useRef<number | null>(null)
  // 用 ref 跟踪最新 state，供事件处理器读取（避免陈旧闭包）
  const stateRef = useRef(state)
  stateRef.current = state

  const selecting = useRef(false)
  const dragStart = useRef<{ x: number; y: number } | null>(null)
  const dragItem = useRef<number | null>(null)
  const dragMods = useRef({ meta: false, shift: false, ctrl: false })

  // ---- 测量视口宽度 ----
  useEffect(() => {
    const el = viewportRef.current
    if (!el) return
    const ro = new ResizeObserver(() => {
      const w = el.clientWidth
      if (w > 0) setCw(w)
    })
    ro.observe(el)
    setCw(el.clientWidth)
    return () => ro.disconnect()
  }, [])

  const layout = useMemo(() => layoutFor(state.view, cw), [state.view, cw])
  const vis = useMemo(
    () => visibleRange(state.view, cw, state.scrollTop, viewportRef.current?.clientHeight ?? 600),
    [state.view, cw, state.scrollTop],
  )
  const selSet = useMemo(() => new Set(state.selection), [state.selection])

  // ---- 焦点变化 → 滚动到视野（含虚拟滚动下的两步定位）----
  useEffect(() => {
    const f = state.focus
    if (f == null) return
    const vp = viewportRef.current
    if (!vp) return
    const el = itemEls.current.get(f)
    if (el) {
      el.scrollIntoView({ block: "nearest" })
    } else if (pendingScroll.current != null) {
      const target = pendingScroll.current
      pendingScroll.current = null
      vp.scrollTop = target
      // 触发重渲染让目标行进入 DOM
      dispatch({ kind: "SCROLL", top: vp.scrollTop })
    }
  }, [state.focus, vis.start, vis.end])

  // ---- 键盘：仅当文件列表获得焦点时生效 ----
  const setView = (view: ViewMode) => {
    const vp = viewportRef.current
    const currentLayout = layoutFor(state.view, cw)
    const nextLayout = layoutFor(view, cw)
    const viewportHeight = vp?.clientHeight ?? 600
    const centerY = (vp?.scrollTop ?? state.scrollTop) + viewportHeight / 2
    const anchorIndex = Math.min(
      ITEMS.length - 1,
      Math.max(
      0,
      Math.floor(centerY / (state.view === "grid" ? GRID_CELL_H : LIST_ROW_H)) * currentLayout.cpr,
    ),
    )
    const anchorRect = cellRect(view, anchorIndex, cw)
    const nextTop = clamp(
      anchorRect.top - (viewportHeight - anchorRect.h) / 2,
      0,
      Math.max(0, nextLayout.totalH - viewportHeight),
    )
    dispatch({ kind: "VIEW", view })
    pendingScroll.current = nextTop
    requestAnimationFrame(() => {
      const currentViewport = viewportRef.current
      if (!currentViewport) return
      currentViewport.scrollTop = nextTop
      dispatch({ kind: "SCROLL", top: nextTop })
    })
  }

  const onKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
    const s = stateRef.current
    const meta = e.metaKey || e.ctrlKey
    if (meta && (e.key === "a" || e.key === "A")) {
      e.preventDefault()
      dispatch({ kind: "SELECT_ALL" })
      return
    }
    if (e.key === "Escape") {
      e.preventDefault()
      dispatch({ kind: "CLEAR" })
      return
    }
    if (!meta && (e.key === "v" || e.key === "V")) {
      setView(s.view === "grid" ? "list" : "grid")
      return
    }
    const dirMap: Record<string, "up" | "down" | "left" | "right"> = {
      ArrowUp: "up",
      ArrowDown: "down",
      ArrowLeft: "left",
      ArrowRight: "right",
    }
    if (!(e.key in dirMap)) return

    e.preventDefault()
    const from = s.focus ?? 0
    const to = nextIndex(s.view, from, dirMap[e.key], layoutFor(s.view, cw).cpr)
    if (to === from) return

    const vpH = viewportRef.current?.clientHeight ?? 600
    const totalH = layoutFor(s.view, cw).totalH
    pendingScroll.current = scrollTarget(s.view, cw, to, vpH, totalH)
    dispatch({
      kind: "NAVIGATE",
      dir: dirMap[e.key],
      extend: e.shiftKey,
      from,
      to,
    })
  }

  // ---- 鼠标：框选 + item 点击 ----
  const onMouseDown = (e: React.MouseEvent) => {
    if (e.button !== 0) return
    const target = e.target as HTMLElement
    const elItem = target.closest("[data-item-id]") as HTMLElement | null
    const mods = { meta: e.metaKey, shift: e.shiftKey, ctrl: e.ctrlKey }
    const vp = viewportRef.current
    if (!vp) return
    const rect = vp.getBoundingClientRect()
    const sx = e.clientX - rect.left
    const sy = e.clientY - rect.top + vp.scrollTop

    dragStart.current = { x: sx, y: sy }
    dragMods.current = mods

    if (elItem) {
      dragItem.current = Number(elItem.getAttribute("data-item-id"))
      selecting.current = false
    } else {
      dragItem.current = null
      selecting.current = true
      setBand(null)
      if (!mods.meta && !mods.shift && !mods.ctrl) {
        dispatch({ kind: "CLICK_EMPTY" })
      }
    }
  }

  useEffect(() => {
    const TH = 4
    const move = (e: MouseEvent) => {
      if (!dragStart.current) return
      const vp = viewportRef.current
      if (!vp) return
      const rect = vp.getBoundingClientRect()
      const x = e.clientX - rect.left
      const y = e.clientY - rect.top + vp.scrollTop
      const dx = x - dragStart.current.x
      const dy = y - dragStart.current.y

      if (!selecting.current) {
        if (Math.abs(dx) < TH && Math.abs(dy) < TH) return
        // 修饰键保留给范围/切换点击，不进入框选
        if (dragMods.current.shift || dragMods.current.meta || dragMods.current.ctrl) return
        selecting.current = true
      }

      const box = normalizeBox(dragStart.current, { x, y })
      setBand(box)
    }

    const up = () => {
      if (!dragStart.current) return
      const wasSelecting = selecting.current
      const start = dragStart.current
      const mods = dragMods.current
      const item = dragItem.current
      dragStart.current = null
      selecting.current = false
      setBand(null)

      if (wasSelecting) {
        const vp = viewportRef.current
        const rect = vp?.getBoundingClientRect()
        const endX = rect ? lastClientX - rect.left : start.x
        const endY = rect ? lastClientY - rect.top + (vp?.scrollTop ?? 0) : start.y
        const box = normalizeBox(start, { x: endX, y: endY })
        const additive = mods.meta || mods.ctrl
        const ids = hitTest(stateRef.current.view, cw, box)
        if (box.w > 2 || box.h > 2) {
          dispatch({ kind: "BOX", ids, additive, box })
        }
      } else if (item != null) {
        dispatch({ kind: "CLICK_ITEM", id: item, modifiers: mods })
      }
    }

    let lastClientX = 0
    let lastClientY = 0
    const track = (e: MouseEvent) => {
      lastClientX = e.clientX
      lastClientY = e.clientY
    }
    window.addEventListener("mousemove", move)
    window.addEventListener("mousemove", track)
    window.addEventListener("mouseup", up)
    return () => {
      window.removeEventListener("mousemove", move)
      window.removeEventListener("mousemove", track)
      window.removeEventListener("mouseup", up)
    }
  }, [cw])

  // ---- item ref 记录 ----
  const setItemRef = (id: number) => (el: HTMLDivElement | null) => {
    if (el) itemEls.current.set(id, el)
    else itemEls.current.delete(id)
  }

  // ---- 渲染可见 item ----
  const rendered: React.ReactNode[] = []
  for (let i = vis.start; i <= vis.end; i++) {
    const f = ITEMS[i]
    const r = cellRect(state.view, i, cw)
    const selected = selSet.has(i)
    const focused = state.focus === i
    rendered.push(
      <div
        key={i}
        ref={setItemRef(i)}
        data-item-id={i}
        id={`file-item-${i}`}
        role="option"
        aria-selected={selected}
        tabIndex={-1}
        title={`${f.name}\n${fmtDate(f.modifiedAt)} · ${fmtSize(f.size)}`}
        style={{
          position: "absolute",
          top: r.top,
          left: r.left,
          width: r.w,
          height: r.h,
          padding: state.view === "grid" ? 10 : 0,
          cursor: "pointer",
          outline: "none",
          background: selected ? "var(--accent-subtle)" : "transparent",
        }}
      >
        <CellView item={f} view={state.view} selected={selected} focused={focused} />
      </div>,
    )
  }

  const cmdText = fmtCommand(state.last)

  return (
    <div
      style={{
        width: "100vw",
        height: "100vh",
        display: "flex",
        flexDirection: "column",
        background: "var(--bg-primary)",
        fontFamily:
          '"Noto Sans SC", system-ui, -apple-system, "PingFang SC", sans-serif',
      }}
    >
      {/* 顶部信息栏 */}
      <div
        style={{
          padding: "10px 18px",
          display: "flex",
          alignItems: "center",
          gap: 16,
          flexWrap: "wrap",
          background: "var(--bg-secondary)",
          boxShadow: "var(--shadow-sm)",
        }}
      >
        <div style={{ display: "flex", flexDirection: "column" }}>
          <span
            style={{
              fontSize: 15,
              fontWeight: 700,
              color: "var(--text-primary)",
              letterSpacing: 0.4,
            }}
          >
            文件管理器 · 命令模式 Demo
          </span>
          <span style={{ fontSize: 11, color: "var(--text-muted)" }}>
            单向数据流 / 框选 / Shift 多选 / ⌘ 切换 / 方向键导航 ·{" "}
            {ITEMS.length.toLocaleString()} 项
          </span>
        </div>
        <div style={{ marginLeft: "auto", display: "flex", alignItems: "center", gap: 10 }}>
          <Toggle
            label="缩略图"
            active={state.view === "grid"}
            onClick={() => setView("grid")}
          />
          <Toggle
            label="列表"
            active={state.view === "list"}
            onClick={() => setView("list")}
          />
        </div>
      </div>

      {/* 状态栏：命令 / 选中 / 渲染窗口 */}
      <div
        style={{
          padding: "8px 18px",
          display: "flex",
          gap: 18,
          flexWrap: "wrap",
          alignItems: "center",
          background: "var(--bg-tertiary)",
          fontSize: 12,
        }}
      >
        <Stat
          k="当前命令"
          v={
            <>
              <code
                style={{
                  padding: "1px 6px",
                  borderRadius: 4,
                  background: "var(--bg-card)",
                  fontSize: 11,
                }}
              >
                {cmdText.key}
              </code>{" "}
              <span style={{ color: "var(--text-muted)" }}>{cmdText.detail}</span>
            </>
          }
        />
        <Stat
          k="已选中"
          v={
            <>
              <b style={{ color: "var(--accent)", fontSize: 14 }}>{state.selection.length}</b>
              <span style={{ color: "var(--text-muted)" }}>
                {" "}
                / {ITEMS.length.toLocaleString()}
              </span>
            </>
          }
        />
        <Stat
          k="可见窗口"
          v={
            <>
              {vis.start} – {vis.end}
              <span style={{ color: "var(--text-muted)" }}> ({vis.end - vis.start + 1} 项)</span>
            </>
          }
        />
        <Stat
          k="虚拟总高"
          v={
            <>
              {Math.round(layout.totalH).toLocaleString()}px ·{" "}
              {state.view === "grid" ? `${layout.cpr} 列` : "1 列"}
            </>
          }
        />
        <Stat k="scrollTop" v={<>{Math.round(state.scrollTop)}px</>} />
        <Stat k="视口宽" v={<>{cw}px</>} />
        <span style={{ marginLeft: "auto", color: "var(--text-secondary)", fontSize: 11 }}>
          ⌘A 全选 · Esc 清空 · V 切视图 · 方向键导航 · Shift+方向键扩展 · 拖拽框选 · Shift/Meta+点选
        </span>
      </div>

      {/* 内容区 */}
      <div style={{ flex: 1, minHeight: 0, position: "relative" }}>
        <div
          ref={viewportRef}
          onScroll={() => {
            const vp = viewportRef.current
            if (vp) dispatch({ kind: "SCROLL", top: vp.scrollTop })
          }}
          onMouseDown={onMouseDown}
          onKeyDown={onKeyDown}
          style={{
            position: "absolute",
            inset: 0,
            overflow: "auto",
            outline: "none",
            userSelect: "none",
          }}
          role="listbox"
          aria-multiselectable="true"
          aria-activedescendant={state.focus != null ? `file-item-${state.focus}` : undefined}
          aria-label="文件管理器内容"
          tabIndex={0}
        >
          <div
            style={{
              position: "relative",
              width: "100%",
              height: layout.totalH,
              overflow: "hidden",
            }}
          >
            {rendered}
            {band && (
              <div
                style={{
                  position: "absolute",
                  left: band.x,
                  top: band.y,
                  width: Math.max(0, band.w),
                  height: Math.max(0, band.h),
                  // 用透明 accent 覆盖层保留框内文件的可读性。
                  background: "var(--accent)",
                  opacity: 0.18,
                  boxShadow: "inset 0 0 0 1px var(--accent)",
                  pointerEvents: "none",
                }}
              />
            )}
          </div>
        </div>
      </div>

      {/* 底部辅助 */}
      <div
        style={{
          padding: "6px 18px",
          display: "flex",
          gap: 16,
          alignItems: "center",
          background: "var(--bg-secondary)",
          fontSize: 11,
          color: "var(--text-muted)",
          boxShadow: "0 -1px 2px rgba(0,0,0,0.04)",
        }}
      >
        <span>命令模式 + useReducer 单向流</span>
        <span>·</span>
        <span>
          固定尺寸虚拟滚动（窗口化渲染 ~{vis.end - vis.start + 1} 项，不引三方库）
        </span>
        <span style={{ marginLeft: "auto" }}>复用主题 token / 无边框阴影分层</span>
      </div>
    </div>
  )
}

