// ============================================================
//  导航 / 滚动目标几何
// ============================================================
function nextIndex(
  view: ViewMode,
  from: number,
  dir: "up" | "down" | "left" | "right",
  cpr: number,
): number {
  if (view === "list") {
    if (dir === "up" || dir === "left") return Math.max(0, from - 1)
    return Math.min(ITEMS.length - 1, from + 1)
  }
  const col = from % cpr
  switch (dir) {
    case "left":
      return col > 0 ? from - 1 : from
    case "right":
      return col < cpr - 1 ? from + 1 : from
    case "up":
      return from - cpr >= 0 ? from - cpr : from
    case "down":
      return Math.min(ITEMS.length - 1, from + cpr)
    default:
      return from
  }
}

function scrollTarget(
  view: ViewMode,
  cw: number,
  idx: number,
  vpH: number,
  totalH: number,
): number {
  const c = cellRect(view, idx, cw)
  return clamp(c.top - (vpH - c.h) / 2, 0, Math.max(0, totalH - vpH))
}

function normalizeBox(
  a: { x: number; y: number },
  b: { x: number; y: number },
): BoxRect {
  return {
    x: Math.min(a.x, b.x),
    y: Math.min(a.y, b.y),
    w: Math.abs(a.x - b.x),
    h: Math.abs(a.y - b.y),
  }
}

